// Historical analytics reads use their own bounded HTTP transport. The existing
// game provider retains its signing/broadcast behavior. Chain validation is done
// explicitly by the auditor (eth_chainId), not by background network retries.
function crearProveedorLecturaImpacto(rpcUrl, chainId) {
  const request = new ethers.FetchRequest(rpcUrl);
  request.timeout = 20000;
  request.setThrottleParams({ maxAttempts: 1 });
  request.retryFunc = async () => false;
  return new ethers.JsonRpcProvider(request, Number(chainId), {
    staticNetwork: true, batchMaxCount: 1, cacheTimeout: 0
  });
}

