// =============================================================================
// PLAYER STATS — Modelo MongoDB + Rutas de sincronización con InvoiceSystem
// Sincroniza vida, agua, comida, oro, plata con el smart contract.
// =============================================================================

const playerStatsSchema = new mongoose.Schema({
  playerName: { type: String, required: true, unique: true, index: true },
  address:    { type: String, required: true, lowercase: true, index: true },
  // Escala de juego 0..100 (las barras se pintan como `${valor}%` sin dividir).
  // Antes el default era 100000 y, combinado con el piso Math.max del sync,
  // producía barras de "100000%".
  // NOTA: sin validador `max` a propósito — hay documentos viejos con 100000 y
  // un max haría fallar su .save() con error de validación. El recorte se hace
  // con clampStat() al escribir y al responder.
  vida:       { type: Number, default: 100, min: 0 },
  agua:       { type: Number, default: 100, min: 0 },
  comida:     { type: Number, default: 100, min: 0 },

  /* VIDA CONGELADA MIENTRAS ESTÁS MUERTO.

     Quién manda sobre estar muerto es GamePlayer.isGhost, pero la regeneración
     pasiva trabaja sobre ESTE documento y no lee aquél. Antes que hacer una
     lectura cruzada en cada tic —que es el camino caliente, se llama en casi
     todas las rutas— se apunta aquí la misma decisión en el único momento en
     que puede cambiar: al morir y al revivir.

     Sin esto la vida del fantasma trepaba sola desde 0 mientras esperaba a
     pagar el revivir. */
  vidaCongelada: { type: Boolean, default: false },
  oro:        { type: Number, default: 0,      min: 0 },
  plata:      { type: Number, default: 0,      min: 0 },
  // (2026-10-20) La moneda de bronce: 1 de plata = 1000 de bronce. Su tabla
  // en el contrato de estadísticas es `bronce`, igual que `oro` y `plata`.
  bronce:     { type: Number, default: 0,      min: 0 },
  // Experiencia del personaje (GamePlayer.nivel_exp). Se lleva al contrato con
  // su propia tabla `exp`, igual que oro y plata.
  exp:        { type: Number, default: 0,      min: 0 },
  invoiceIds: {
    vida:   { type: Number, default: null },
    agua:   { type: Number, default: null },
    comida: { type: Number, default: null },
    oro:    { type: Number, default: null },
    plata:  { type: Number, default: null },
    bronce: { type: Number, default: null },
    exp:    { type: Number, default: null },
  },
  manualIds: {
    vida:   { type: String, default: null },
    agua:   { type: String, default: null },
    comida: { type: String, default: null },
    oro:    { type: String, default: null },
    plata:  { type: String, default: null },
    bronce: { type: String, default: null },
    exp:    { type: String, default: null },
  },
  // Marca de tiempo de la ÚLTIMA regeneración pasiva de vitales aplicada.
  // La regeneración se calcula por diferencia de tiempo (ver
  // applyGhostVitalRegen), así que también cuenta el rato que el jugador estuvo
  // DESCONECTADO sin necesidad de ningún temporizador por jugador.
  lastFullVitalHeal: { type: Date, default: null },
  lastDamageAt: { type: Date, default: null },
  swordGuardReady: { type: Date, default: null },
  swordGuardUntil: { type: Date, default: null },
  lastVitalRegen: { type: Date, default: null },
  // DEUDA CON LA CADENA (liquidación agrupada, 2026-08-05).
  // Lista de stats cuyo valor en Mongo ya está cobrado pero todavía no se ha
  // escrito en su factura. El liquidador (liquidarPendientesDeCadena) las
  // convierte en UNA transacción por barra cada minuto. Vive en la BASE DE
  // DATOS a propósito: si el jugador recarga o cierra el navegador, la deuda
  // sigue aquí y se liquida igual — no hay forma de escaparse gastando y
  // recargando la página.
  chainPending:      { type: [String], default: [] },
  chainPendingSince: { type: Date, default: null },

  // ── RESTO FRACCIONARIO DE LOS COSTES ───────────────────────────────────────
  // Las barras vitales son NÚMEROS ENTEROS, pero varias acciones cuestan
  // fracciones: sembrar vale 0,2 de comida y regar 0,5 de agua.
  //
  // BUG QUE ESTO ARREGLA: /consume hacía `Math.round(coste)` y descartaba lo
  // que diera 0. O sea que 0,2 de comida se convertía en 0 y sembrar NUNCA ha
  // costado comida, mientras que 0,5 de agua se redondeaba a 1 y regar costaba
  // el DOBLE de lo definido.
  //
  // Ahora el sobrante se guarda aquí y se arrastra a la siguiente acción:
  // sembrar cinco veces (5 × 0,2) cobra 1 de comida, que es justo lo que la
  // tabla de cultivos quería decir. Vive en la base de datos para que no se
  // pueda tirar recargando la página.
  vitalFractions: {
    vida:   { type: Number, default: 0 },
    agua:   { type: Number, default: 0 },
    comida: { type: Number, default: 0 }
  },

  lastSync:    { type: Date, default: null },
  lastUpdated: { type: Date, default: Date.now },
  createdAt:   { type: Date, default: Date.now },
}, { collection: 'player_stats', timestamps: { createdAt: 'createdAt', updatedAt: 'lastUpdated' } });

const PlayerStats = mongoose.model('PlayerStats', playerStatsSchema);

const STAT_TYPES_LIST    = ['vida', 'agua', 'comida', 'oro', 'plata', 'bronce', 'exp'];

// ⚠️ ESCALA DE LAS VITALES: en el juego las barras se pintan como `${valor}%`
// SIN dividir, así que la escala real de vida/agua/comida es 0..100.
// Antes estos mapas estaban en 100000 y eso causaba DOS bugs:
//   • "100000%": el sync usaba STAT_DEFAULTS_MAP como PISO (Math.max), así que
//     un valor legítimo bajo (0, 1, o tu 34%) saltaba a 100000.
//   • "7%" / "5%" en jugadores nuevos: la factura se creaba pidiendo 100000
//     unidades, lo que agota el cupo (`limit`) del tipo en el contrato; cuando
//     quedaban 7 o 5 disponibles, el jugador nuevo nacía con 7% o 5%.
const VITAL_MAX          = 100;
const STAT_DEFAULTS_MAP  = { vida: VITAL_MAX, agua: VITAL_MAX, comida: VITAL_MAX, oro: 0, plata: 0, bronce: 0, exp: 0 };
// Valores con los que se CREA la factura de un jugador nuevo. Separado de
// STAT_DEFAULTS_MAP porque ese mapa actúa como "piso" en el sync — si oro/plata
// tuvieran piso 1000, cada sync regalaría monedas a jugadores que ya gastaron.
const STAT_INITIAL_MAP   = { vida: VITAL_MAX, agua: VITAL_MAX, comida: VITAL_MAX, oro: 1000, plata: 1000, bronce: 1000, exp: 0 };

const isVitalStat = (stat) => stat === 'vida' || stat === 'agua' || stat === 'comida';
const VITAL_STATS = ['vida', 'agua', 'comida'];
// Acota un stat a su rango válido: las vitales a 0..100; oro/plata/exp solo a >= 0.
function clampStat(stat, value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n < 0) return 0;
  return isVitalStat(stat) ? Math.min(VITAL_MAX, n) : n;
}

// =============================================================================
// REGENERACIÓN PASIVA DE VITALES — "MODO FANTASMA"            (2026-08-05)
// -----------------------------------------------------------------------------
// Pedido: vida, agua y comida suben cada 3 MINUTOS, esté el jugador conectado
// o no. (Antes era cada minuto; se bajó el ritmo a un tercio.)
//
// Hacerlo con una transacción por tic y por jugador es inviable (miles de
// transacciones al día por cuenta, casi todas para sumar 1). Así que la subida
// se lleva en MODO FANTASMA: vive solo en Mongo y se calcula por DIFERENCIA DE
// TIEMPO contra `lastVitalRegen`. Ventajas:
//
//   • No hace falta ningún temporizador por jugador: el valor correcto se
//     obtiene en el momento en que alguien lo lee.
//   • El tiempo DESCONECTADO cuenta igual que el conectado (es la misma resta).
//   • Cero transacciones mientras solo se regenera.
//
// La cadena se pone al día SOLA en el primer movimiento real del jugador
// (gastar, recargar, sincronizar): applyStatOnChain calcula el delta contra la
// cantidad REAL de la factura, así que al escribir el valor ya regenerado la
// factura salta directamente al número correcto con UNA sola transacción.
//
// Regla de convergencia: el fantasma solo SUMA. Por eso, cuando Mongo va por
// delante de la cadena en una vital, gana Mongo (es regeneración pendiente de
// materializar); cuando va por detrás, gana la cadena (hubo un gasto).
// =============================================================================
// RITMO DE REGENERACIÓN.
// Cada "tic" suma VITAL_REGEN_PER_TICK puntos a cada barra vital.
// El tic dura VITAL_REGEN_TICK_MS: 3 minutos (antes era 1).
// Llenar una barra desde cero pasa de 100 min a 300 min (5 h).
const VITAL_REGEN_TICK_MS   = 3 * 60 * 1000;
const VITAL_REGEN_PER_TICK  = 1;
// Tope de acumulación: aunque la cuenta lleve meses parada, como mucho se
// aplican los tics necesarios para llenar las barras desde cero.
const VITAL_REGEN_MAX_TICKS = Math.ceil(VITAL_MAX / VITAL_REGEN_PER_TICK);

/**
 * Aplica al documento (en memoria, sin guardar ni tocar la cadena) la
 * regeneración acumulada desde `lastVitalRegen`.
 *
 * El reloj avanza SIEMPRE que pase al menos un tic, aunque las barras ya
 * estuvieran llenas; si no, un jugador con todo al 100 % acumularía "crédito"
 * infinito y al gastar se le rellenaría al instante.
 *
 * @returns {{changed:boolean, minutes:number, gain:number}}
 *   `minutes` conserva el nombre por compatibilidad con quien lo lee, pero
 *   ahora cuenta TICS de VITAL_REGEN_TICK_MS, no minutos.
 */
function applyGhostVitalRegen(doc, now = new Date()) {
  if (!doc) return { changed: false, minutes: 0, gain: 0 };

  const healed = gfFullVitalHealing(doc, now);
  const ahora = now.getTime();
  if (!doc.lastVitalRegen) {
    // Primera vez que se ve a este jugador: se arranca el reloj, sin regalar nada.
    doc.lastVitalRegen = now;
    return { changed: healed, minutes: healed ? 1 : 0, gain: healed ? 1 : 0 };
  }

  const desde = new Date(doc.lastVitalRegen).getTime();
  const tics  = Math.floor((ahora - desde) / VITAL_REGEN_TICK_MS);
  if (tics <= 0) return { changed: healed, minutes: healed ? 1 : 0, gain: healed ? 1 : 0 };

  // El resto NO se pierde: el reloj avanza solo los tics enteros consumidos,
  // así que los segundos sobrantes cuentan para el próximo tic.
  doc.lastVitalRegen = new Date(desde + tics * VITAL_REGEN_TICK_MS);

  const ganancia = Math.min(tics, VITAL_REGEN_MAX_TICKS) * VITAL_REGEN_PER_TICK;
  let changed = healed;
  for (const stat of VITAL_STATS) {
    /* MUERTO NO SE CURA SOLO.

       EL FALLO QUE ARREGLA: la regeneración pasiva subía las TRES barras sin
       mirar si el jugador estaba muerto, así que un fantasma veía cómo su vida
       trepaba desde 0 mientras esperaba a pagar el revivir. Además el propio
       vigilante de muerte podía dejar de verla en 0 y sacarlo del estado
       fantasma sin haber pagado.

       Agua y comida sí siguen subiendo: el hambre y la sed no se paran porque
       te hayan mordido, y no dan nada gratis. */
    if (stat === 'vida' && doc.vidaCongelada) continue;
    const actual = clampStat(stat, doc[stat]);
    const nuevo  = clampStat(stat, actual + ganancia);
    if (nuevo !== doc[stat]) { doc[stat] = nuevo; changed = true; }
  }
  return { changed, minutes: tics, gain: ganancia };
}

/**
 * Igual que applyGhostVitalRegen, pero además persiste en Mongo si hubo algún
 * cambio (incluido el avance del reloj). NO manda transacciones: la cadena se
 * pone al día en el siguiente movimiento real.
 */
async function regenerarVitalesEnBD(doc, now = new Date()) {
  const r = applyGhostVitalRegen(doc, now);
  if (r.minutes > 0) {
    try { await doc.save(); }
    catch (e) { console.warn('⚠️  No se pudo guardar la regeneración fantasma:', e.message); }
  }
  return r;
}

// =============================================================================
// LIQUIDACIÓN AGRUPADA DE VITALES — 1 TRANSACCIÓN POR BARRA   (2026-08-05)
// -----------------------------------------------------------------------------
// PROBLEMA de la versión anterior: /consume escribía en la cadena EN EL ACTO,
// una transacción por barra y por golpe. Talar un árbol de 7 golpes = 14
// transacciones, y encima el jugador esperaba cada una. Absurdo: la barra de
// agua es UN número, no hace falta escribirlo 7 veces para bajarlo 7 puntos.
//
// AHORA hay dos tiempos distintos:
//
//   1. COBRO (instantáneo, autoritativo).  /consume comprueba el saldo y lo
//      descuenta en Mongo al momento. El jugador no espera a ninguna cadena, y
//      el servidor ya decidió: si no había saldo, la acción no ocurre.
//
//   2. LIQUIDACIÓN (agrupada, cada minuto). Un trabajador de fondo coge lo que
//      esté marcado en `chainPending` y escribe el valor ACTUAL de cada barra
//      en su factura: UNA transacción por barra, por mucho que el jugador haya
//      dado 50 golpes en ese minuto. applyStatOnChain calcula el delta contra
//      la cantidad real de la factura, así que un solo movimiento la deja en el
//      número correcto.
//
// POR QUÉ LA DEUDA VIVE EN MONGO Y NO EN EL NAVEGADOR: si el jugador recarga la
// página, cierra la pestaña o se le va internet justo después de gastar, la
// marca sigue en la base de datos y el trabajador la liquida igual. No se puede
// "huir" de un consumo recargando el navegador. Y si se reinicia el servidor,
// el arranque hace una pasada de liquidación con lo que quedara pendiente.
// =============================================================================

// Cuánto espera una deuda antes de escribirse en la cadena.
const CHAIN_SETTLE_DELAY_MS   = 60 * 1000;
// Cada cuánto mira el trabajador si hay algo que liquidar.
const CHAIN_SETTLE_TICK_MS    = 20 * 1000;
// Cuántos jugadores se liquidan por ronda (para no saturar el relayer).
const CHAIN_SETTLE_BATCH      = 25;

/** Apunta que estos stats han cambiado en Mongo y deben escribirse en la cadena. */
function marcarPendienteDeCadena(doc, stats) {
  if (!doc) return;
  const lista = new Set(Array.isArray(doc.chainPending) ? doc.chainPending : []);
  let añadido = false;
  for (const s of [].concat(stats || [])) {
    if (STAT_TYPES_LIST.includes(s) && !lista.has(s)) { lista.add(s); añadido = true; }
  }
  if (!añadido) return;
  doc.chainPending = Array.from(lista);
  if (!doc.chainPendingSince) doc.chainPendingSince = new Date();
  doc.markModified('chainPending');
}

/**
 * Escribe en la cadena TODOS los stats pendientes de un jugador: una sola
 * transacción por stat, con el valor que tenga Mongo en este momento.
 *
 * Un stat solo se saca de la lista si su transacción salió bien; si falla
 * (nodo caído, sin cupo) se queda pendiente y se reintenta en la ronda
 * siguiente, así que la deuda nunca se pierde en silencio.
 *
 * @returns {{liquidados:string[], fallidos:string[]}}
 */
async function liquidarPendientesDeCadena(doc) {
  const pendientes = Array.isArray(doc.chainPending) ? doc.chainPending.slice() : [];
  if (!pendientes.length) return { liquidados: [], fallidos: [] };

  const contract = getStatsContract();
  if (!contract) return { liquidados: [], fallidos: pendientes };

  const gasPrice   = await getSafeGasPriceStats();
  const liquidados = [];
  const fallidos   = [];

  for (const stat of pendientes) {
    const invId = doc.invoiceIds && doc.invoiceIds[stat];
    if (!invId) {
      // Todavía no hay factura: la creará /sync con el valor de Mongo, así que
      // esta deuda ya está cubierta y deja de estar pendiente.
      liquidados.push(stat);
      continue;
    }
    const objetivo = clampStat(stat, doc[stat]);
    const r = await applyStatOnChain(contract, stat, invId, objetivo, gasPrice);
    if (r.ok) {
      liquidados.push(stat);
    } else {
      console.error(`❌ liquidación [${stat}] de ${doc.playerName}:`, r.error);
      fallidos.push(stat);
    }
  }

  doc.chainPending      = fallidos;
  doc.chainPendingSince = fallidos.length ? (doc.chainPendingSince || new Date()) : null;
  doc.markModified('chainPending');
  try { await doc.save(); }
  catch (e) { console.warn('⚠️  No se pudo guardar tras liquidar:', e.message); }

  if (liquidados.length) {
    console.log(`⛓️  Liquidado [${liquidados.join(', ')}] de ${doc.playerName} ` +
                `(vida=${doc.vida} agua=${doc.agua} comida=${doc.comida})`);
  }
  return { liquidados, fallidos };
}

// Evita que dos rondas se pisen si una tarda más que el intervalo.
let _liquidacionEnCurso = false;

async function rondaDeLiquidacion({ inmediato = false } = {}) {
  if (_liquidacionEnCurso) return;
  if (!relayerWallet) return;
  _liquidacionEnCurso = true;
  try {
    const limite = new Date(Date.now() - (inmediato ? 0 : CHAIN_SETTLE_DELAY_MS));
    const docs = await PlayerStats.find({
      'chainPending.0':  { $exists: true },
      chainPendingSince: { $lte: limite }
    }).limit(CHAIN_SETTLE_BATCH);

    for (const doc of docs) {
      try { await liquidarPendientesDeCadena(doc); }
      catch (e) { console.error(`❌ Error liquidando ${doc.playerName}:`, e.message); }
    }
  } catch (e) {
    console.error('❌ Error en la ronda de liquidación:', e.message);
  } finally {
    _liquidacionEnCurso = false;
  }
}

// =============================================================================
// REGLA: UNA SOLA FACTURA POR (JUGADOR, STAT)
// =============================================================================
// vida, agua, comida, oro, plata y exp tienen EXACTAMENTE UNA factura por
// jugador en el contrato. El backend es el único que la crea y el único que la
// mueve, siempre con increase/decreaseInvoiceQuantity sobre ESE id.
//
// Reglas que se derivan de eso y que este módulo hace cumplir:
//   1. La factura canónica es la que tiene manualId == buildStatManualId(addr,stat).
//      Si por historia hay más de una factura del mismo tipo para el jugador,
//      el sync las CONSOLIDA (fungibles: se mueve el saldo a la canónica;
//      vitales: se queman) hasta dejar una sola.
//   2. Nunca se crea una factura "a medias". Antes, si al tipo le quedaban 12
//      unidades de cupo, el jugador nuevo nacía con 12% de agua y 7% de comida.
//      Ahora el cupo del tipo se ASEGURA primero (ensureStatTipo) y solo
//      después se crea la factura con el valor completo.
//   3. El delta de cada increase/decrease se calcula contra la cantidad REAL
//      leída del contrato, no contra el valor de Mongo. Si los dos se separan
//      (una TX falló antes), la cadena converge igual al valor pedido.
//   4. Si una TX falla, el valor que se devuelve al cliente es el de la cadena.
//      Nunca se responde "30" cuando en la cadena quedaron 12.
// -----------------------------------------------------------------------------

// Piso en la cadena: bajar una factura a 0 la DESACTIVA y libera su manualId
// (ver decreaseInvoiceQuantity en el contrato). Como la regla es "una sola
// factura y siempre la misma", jamás se baja de 1. El 0 real vive en Mongo.
const STAT_CHAIN_FLOOR = 1;

// Configuración de cada tabla (tipo) en el contrato.
//   perInvoiceLimit → techo de UNA factura. Para las vitales es 100 (la escala
//                     del juego); para oro/plata/exp, un techo alto.
//   headroom        → cupo global libre por debajo del cual se considera que
//                     la tabla se está quedando corta.
//   autoRaise       → si el backend puede subir `limit` por su cuenta cuando se
//                     queda sin cupo.
//
// autoRaise está en true para las SEIS tablas. El fallo de "recargo 30 de agua
// y al refrescar tengo 12" era una tabla sin cupo: increaseInvoiceQuantity
// revertía y el valor se perdía en silencio. Ese mismo fallo puede pasarle a
// oro, plata y exp, así que las seis se amplían solas.
//
// Nota sobre oro y plata: ampliar `limit` sube el techo de emisión de la
// moneda. Se hace porque perder el oro de un jugador es peor que tener un techo
// alto, pero cada ampliación queda registrada en el log con el prefijo
// `setLimit[oro]` / `setLimit[plata]` para que se pueda auditar. Si en algún
// momento querés congelar la emisión, poné autoRaise en false para esas dos:
// el backend seguirá avisando por log cuando la tabla se quede corta, sin
// tocar el contrato.
const STAT_TIPO_CONFIG = {
  vida:   { perInvoiceLimit: VITAL_MAX,     headroom: 1_000_000, autoRaise: true },
  agua:   { perInvoiceLimit: VITAL_MAX,     headroom: 1_000_000, autoRaise: true },
  comida: { perInvoiceLimit: VITAL_MAX,     headroom: 1_000_000, autoRaise: true },
  oro:    { perInvoiceLimit: 1_000_000_000, headroom: 1_000_000, autoRaise: true },
  plata:  { perInvoiceLimit: 1_000_000_000, headroom: 1_000_000, autoRaise: true },
  bronce: { perInvoiceLimit: 1_000_000_000_000, headroom: 1_000_000_000, autoRaise: true },
  exp:    { perInvoiceLimit: 1_000_000_000, headroom: 1_000_000, autoRaise: true },
};

// Al ampliar una tabla se deja bastante más margen del que dispara la ampliación
// (headroom × este factor). Si se subiera justo hasta el headroom, el propio
// crecimiento normal volvería a cruzar el umbral enseguida y el backend estaría
// mandando un setLimit cada pocos minutos.
const TIPO_RAISE_FACTOR = 10;

// Cache de la config de tipos ya verificada en esta ejecución (evita un
// getTipoStats por stat en cada sync). TTL corto por si se toca desde fuera.
const _tipoCheckCache = new Map(); // stat → { at: ms, info: {...} }
const TIPO_CACHE_TTL_MS = 5 * 60 * 1000;

/**
 * Se asegura de que la tabla `stat` exista en el contrato y tenga cupo para
 * operar: perInvoiceLimit suficiente para una factura llena y `limit` global
 * con headroom por delante. Si falta algo y el tipo es autoRaise, llama a
 * setLimit (el relayer es admin del contrato).
 *
 * Esta es la causa raíz de "agua 12% / comida 7%": el tipo se quedaba sin cupo
 * global, createInvoice truncaba la cantidad e increaseInvoiceQuantity revertía
 * con ExceedsTipoLimit, así que las recargas no llegaban nunca a la cadena.
 *
 * @returns {{exists:boolean, limit:number, perInvoiceLimit:number, totalQuantity:number, available:number}|null}
 */
async function ensureStatTipo(contract, stat, gasPrice, { force = false, minPerInvoice = 0 } = {}) {
  const cfg = STAT_TIPO_CONFIG[stat];
  if (!cfg) return null;

  if (!force) {
    const cached = _tipoCheckCache.get(stat);
    if (cached && (Date.now() - cached.at) < TIPO_CACHE_TTL_MS) return cached.info;
  }

  // Techo por factura que hace falta de verdad. Normalmente es el de la config,
  // pero si un jugador llegó a acumular más oro/plata/exp que ese techo, hay que
  // subirlo por encima o su factura no podría volver a crecer nunca.
  const perInvoiceObjetivo = Math.max(cfg.perInvoiceLimit, Math.ceil(minPerInvoice));

  let info;
  try {
    const ts = await contract.getTipoStats(stat);
    info = {
      totalQuantity:   Number(ts.totalQuantity   ?? ts[0] ?? 0),
      limit:           Number(ts.limit           ?? ts[1] ?? 0),
      perInvoiceLimit: Number(ts.perInvoiceLimit ?? ts[2] ?? 0),
      exists:          Boolean(ts.exists !== undefined ? ts.exists : ts[5]),
    };
  } catch (e) {
    console.warn(`⚠️  ensureStatTipo[${stat}]: getTipoStats falló:`, e.message);
    return null;
  }
  info.available = info.limit > info.totalQuantity ? info.limit - info.totalQuantity : 0;

  const needPerInvoice = info.perInvoiceLimit < perInvoiceObjetivo;
  const needHeadroom   = info.available       < cfg.headroom;

  if (info.exists && !needPerInvoice && !needHeadroom) {
    _tipoCheckCache.set(stat, { at: Date.now(), info });
    return info;
  }

  if (!cfg.autoRaise && info.exists) {
    // oro/plata: no se toca el techo de emisión por nuestra cuenta.
    console.warn(
      `⚠️  Tabla [${stat}] corta en el contrato ` +
      `(perInvoice=${info.perInvoiceLimit}, libre=${info.available}). ` +
      `No se sube automáticamente: ejecutá setLimit('${stat}', ...) desde el owner.`
    );
    _tipoCheckCache.set(stat, { at: Date.now(), info });
    return info;
  }

  const newPerInvoice = Math.max(perInvoiceObjetivo, info.perInvoiceLimit);
  const newLimit      = Math.max(info.limit, info.totalQuantity + cfg.headroom * TIPO_RAISE_FACTOR, newPerInvoice);

  try {
    const nonce = await provider.getTransactionCount(relayerWallet.address, 'pending');
    console.log(
      `🧾 setLimit[${stat}]: limit ${info.limit}→${newLimit}, ` +
      `perInvoice ${info.perInvoiceLimit}→${newPerInvoice}` +
      (info.exists ? '' : ' (tabla nueva)')
    );
    const tx = await contract.setLimit(stat, newLimit, newPerInvoice, { gasPrice, nonce });
    await tx.wait();
    info = {
      exists: true,
      limit: newLimit,
      perInvoiceLimit: newPerInvoice,
      totalQuantity: info.totalQuantity,
      available: newLimit - info.totalQuantity,
    };
    console.log(`✅ Tabla [${stat}] configurada: limit=${newLimit} perInvoice=${newPerInvoice}`);
  } catch (e) {
    console.error(`❌ setLimit[${stat}] falló (¿el relayer es admin?):`, e.message);
  }

  _tipoCheckCache.set(stat, { at: Date.now(), info });
  return info;
}

// Reintento ante caídas del nodo, compartido con el relay. El nodo de LitVM se
// cae y vuelve cada pocos minutos; sin esto, un sync o una actualización de
// stats que caiga en esa ventana pierde el valor del jugador.
const reintentarRPC = (fn, etiqueta) => RelayManager.conReintentoRPC(fn, etiqueta);

/** Lee la cantidad real de una factura. null si no existe o está inactiva. */
async function readInvoiceQty(contract, invId) {
  try {
    const inv = await reintentarRPC(() => contract.getInvoice(invId), `getInvoice(${invId})`);
    if (!inv || Number(inv.id) === 0 || !inv.active) return null;
    return Number(inv.cantidad);
  } catch (_) { return null; }
}

/**
 * Lleva LA factura `invId` de `stat` al valor `target`, con un único
 * increase o decrease. El delta se calcula contra la cantidad real en la
 * cadena, no contra Mongo, para que ambos converjan aunque se hubieran
 * separado antes.
 *
 * @returns {{ok:boolean, chainQty:number, error?:string}} chainQty = cantidad
 *          que quedó realmente en la factura (con el piso de 1 aplicado).
 */
async function applyStatOnChain(contract, stat, invId, target, gasPrice) {
  const desired = Math.max(STAT_CHAIN_FLOOR, Math.round(clampStat(stat, target)));

  let current = await readInvoiceQty(contract, invId);
  if (current === null) return { ok: false, chainQty: null, error: 'invoice_not_found_or_inactive' };
  if (current === desired) return { ok: true, chainQty: current };

  // Envuelto en reintento por caída del nodo: es la misma protección que tiene
  // el relay. Un revert del contrato NO se reintenta aquí (se trata abajo).
  const runTx = () => reintentarRPC(async () => {
    const nonce = await provider.getTransactionCount(relayerWallet.address, 'pending');
    if (desired > current) {
      const delta = desired - current;
      console.log(`⬆️  [${stat}] id=${invId} ${current}→${desired} (+${delta}, nonce=${nonce})`);
      const tx = await contract.increaseInvoiceQuantity(invId, delta, { gasPrice, nonce });
      await tx.wait();
    } else {
      const delta = current - desired;
      console.log(`⬇️  [${stat}] id=${invId} ${current}→${desired} (-${delta}, nonce=${nonce})`);
      const tx = await contract.decreaseInvoiceQuantity(invId, delta, { gasPrice, nonce });
      await tx.wait();
    }
  }, `applyStatOnChain[${stat}]`);

  /* NONCE OCUPADO (2026-10-27). Aquí el nonce se lee de la cadena y el relay
     (/api/relay/transaction) lo saca de relayerNonceManager: con la MISMA
     clave, una compra en la tienda manda a la vez el cobro (aquí) y el
     objeto (allí), y los dos podían salir con el mismo nonce. El que pierde
     recibe "nonce too low": su transacción no entró. Se relee la factura (si
     ya tiene el valor pedido, no queda nada que hacer) y se manda de nuevo
     con un nonce fresco. Hasta 3 veces. */
  const runTxSinChoque = async () => {
    for (let choque = 0; ; choque++) {
      try { return await runTx(); } catch (err) {
        const m = String((err && (err.shortMessage || err.message)) || '').toLowerCase();
        const ocupado = (err && ['NONCE_EXPIRED', 'REPLACEMENT_UNDERPRICED'].includes(err.code)) ||
                        /nonce too low|nonce has already been used|replacement transaction underpriced/.test(m);
        if (!ocupado || choque >= 3) throw err;
        await new Promise(r => setTimeout(r, 400 * (choque + 1)));
        const ahora = await readInvoiceQty(contract, invId);
        if (ahora === null) throw err;
        current = ahora;
        if (current === desired) return;
        console.warn(`🔢 [${stat}] nonce ocupado por otra transacción del relayer; se repite (${choque + 1}/3)`);
      }
    }
  };

  try {
    await runTxSinChoque();
    return { ok: true, chainQty: desired };
  } catch (err) {
    const msg = String(err.message || err);
    // ExceedsTipoLimit / InvoiceWouldExceedPerInvoiceLimit: la tabla se quedó
    // sin cupo. Esto era exactamente lo que hacía que "recargo a 30 y al
    // refrescar tengo 12": la TX revertía y nadie lo notaba. Se amplía el cupo
    // y se reintenta UNA vez.
    if (/ExceedsTipoLimit|PerInvoiceLimit/i.test(msg)) {
      console.warn(`⚠️  [${stat}] sin cupo en la tabla — ampliando y reintentando`);
      // `desired` va como techo mínimo por factura: si el jugador acumuló más
      // oro/plata/exp del que admitía una sola factura, la tabla se amplía lo
      // suficiente para que quepa en vez de quedarse atascada para siempre.
      await ensureStatTipo(contract, stat, gasPrice, { force: true, minPerInvoice: desired });
      try {
        current = await readInvoiceQty(contract, invId);
        if (current === null) return { ok: false, chainQty: null, error: 'invoice_not_found_or_inactive' };
        if (current === desired) return { ok: true, chainQty: current };
        await runTx();
        return { ok: true, chainQty: desired };
      } catch (err2) {
        const after = await readInvoiceQty(contract, invId);
        return { ok: false, chainQty: after, error: String(err2.message || err2) };
      }
    }
    const after = await readInvoiceQty(contract, invId);
    return { ok: false, chainQty: after, error: msg };
  }
}

// =============================================================================
// EL TESORO Y SUS INCENTIVOS                                       (2026-10-22)
// -----------------------------------------------------------------------------
// "En la tiendajuego, si alguien vende o compra se le cobra una comisión del
// 1,5 % y en el control quiero saber cuánto tiene ese tesoro de comisiones;
// así mismo, si alguien vende o compra un objeto en la tienda P2P, el 1,5 % se
// va al tesoro. Dentro del tesoro se repartirá un incentivo: según sea free o
// VIP, su nivel y su suerte, un monstruo o enemigo vencido puede soltar
// monedas que, al tomarlas, no van al inventario sino que se suman a sus
// monedas. En el panel, aunque la probabilidad se ajusta sola, quiero un modo
// manual para subirla o bajarla a los free o a los VIP. Los usuarios sin
// nombre no tienen este mecanismo."
//
// TODO EN BRONCE, la moneda más pequeña (1 plata = 1.000, 1 oro = 1.000.000):
// el 1,5 % de 2 de oro no cabe en oro entero.
//
// LO QUE ENTRA
//   · La tienda del juego: el navegador cobra el 1,5 % (tienda_sistema.js,
//     _comisionBronce) y lo avisa en POST /api/tesoro/comision. El importe NO
//     se toma del navegador: se recalcula con TIENDA_PRECIOS (el mismo
//     catálogo que ve el jugador, tools/tienda-precios-a-servidor.js). Cada
//     aviso lleva un `ref` que solo cuenta una vez, y hay un tope por jugador
//     y día. (El saldo de la tienda lo fija el navegador desde siempre —
//     /api/stats/update—: esto no lo empeora y le pone techo.)
//   · El mercado P2P (marketplace-routes.js): la comisión ya la cobraba el
//     servidor al vendedor; ahora es el 1,5 % y se apunta aquí DENTRO de la
//     misma transacción de Mongo que la venta (se le pasan Tesoro y TesoroMov).
//
// LO QUE SALE
//   · /api/monstruos/derrotado tira los dados (tesoroIncentivo). Si sale, la
//     cantidad se RESERVA (saldo → reservado) y va como un montón más del
//     botín ('moneda_bronce', incentivo: true). Al pisarlo,
//     /api/monstruos/botin/recoger la abona en la moneda de bronce del
//     jugador (PlayerStats, pendiente de cadena): nunca va al inventario.
//     Lo que caduca sin recoger vuelve al saldo; y al arrancar el servidor,
//     las reservas que dejó colgadas el proceso anterior vuelven solas
//     (tesoroListo) antes de reservar nada nuevo.
//   · La probabilidad: AUTO = base free/VIP + nivel + "suerte" (cada monstruo
//     seguido sin premio la sube un poco y se pone a cero al cobrar) o MANUAL =
//     el % que fija el panel para free y para VIP (con o sin esos bonos). Los
//     jefes, el doble. La cantidad: una parte del saldo según lo duro que sea
//     el monstruo, el VIP y el nivel, entre un mínimo y un tope.
//   · Sin nombre (gfNombreValido) no hay incentivo.
//
// EL PANEL: tesoro.html en el centro de control — GET /api/admin/tesoro,
// POST /api/admin/tesoro/config y POST /api/admin/tesoro/ajuste.
// =============================================================================
// <TIENDA_PRECIOS>
const TIENDA_PRECIOS = {"Semillax":[10,5,"p"],"Semillax1":[15,7,"p"],"Semillax2":[8,3,"p"],"Semillax3":[25,12,"p"],"Semillax4":[20,10,"p"],"Regaderax":[120,60,"p"],"Tijerasx":[200,100,"p"],"hacha_de_madera":[300,150,"p"],"pico_de_madera":[400,200,"p"],"zanahoria_buena":[20,14,"p"],"tomate_buena":[28,20,"p"],"trigo_buena":[13,9,"p"],"fresa_buena":[40,28,"p"],"calabaza_buena":[48,34,"p"],"balde_con_agua":[8,3,"p"],"pes1":[0,12,"p"],"pes2":[0,22,"p"],"pes3":[0,70,"p"],"pes4":[0,10,"p"],"pes5":[0,16,"p"],"pes6":[0,95,"p"],"pes7":[0,40,"p"],"pes8":[0,75,"p"],"pes9":[0,32,"p"],"pes10":[0,24,"p"],"pes11":[0,18,"p"],"pes12":[0,160,"p"],"pes13":[0,55,"p"],"pes14":[0,85,"p"],"parcela":[200,100,"p"],"pala_construccion":[300,150,"p"],"espantapajaros":[120,60,"p"],"antorcha":[40,20,"p"],"basura":[120,60,"p"],"cofre1":[2,1,"o"],"cofre2":[0,250,"p"],"cofre3":[0,700,"p"],"cofre4":[0,2000,"p"],"espada_madera":[80,40,"p"],"espada_cobre":[250,125,"p"],"espada_hierro":[600,300,"p"],"cana_pescar":[150,75,"p"],"arco":[300,150,"p"],"baston_mago":[450,225,"p"],"bote":[500,250,"p"]};
// </TIENDA_PRECIOS>
const TESORO_ID = 'principal';
/* (2026-10-26) "La comisión es un 5 % en los dos mercados y se divide: el
   1,5 % es de la economía circular y el 3,5 % del tesoro del juego." */
const TESORO_COMISION_BPS = 500;                       // 5 % en total (tienda del juego y P2P)
const TESORO_CIRCULAR_BPS = 150;                       // de ese 5 %, el 1,5 % al tesoro de la economía circular
const TESORO_BRONCE_POR = Object.freeze({ bronce: 1, plata: 1000, oro: 1000000 });
const TESORO_TOPE_TIENDA_DIA = 20 * 1000000;           // comisión de tienda contada por jugador y día (bronce)
const TESORO_PROB_MAX = 0.75;
const TESORO_CONFIG_BASE = Object.freeze({
  activo: true,
  modo: 'auto',                                        // 'auto' | 'manual'
  manual: Object.freeze({ free: 5, vip: 10, conBonos: false }),            // % por monstruo
  auto: Object.freeze({ baseFree: 4, baseVip: 7, porNivel: 0.25, nivelTope: 40, rachaPaso: 0.5, rachaTope: 6 }),
  parteDelTesoro: 0.25,                                // % del saldo por pago (antes de multiplicadores)
  pagoMin: 100,                                        // bronce
  pagoMax: 250000,                                     // bronce
  vipExtraPago: 1.5,                                   // el VIP cobra más
  topeDiario: 25                                       // premios por jugador y día
});

/* LOS MAPAS POR NIVEL (2026-10-22): "el mapa salvaje en nivel 4, la mina en
   el 2, el de hielo en el 7, el desierto en el 5 y el cementerio en el 6".
   La misma tabla que gf-niveles-mapas.js (el cliente ni deja entrar); aquí,
   para que nadie gane nada por debajo y para el botón de amigos. */
const GF_NIVEL_MAPA = Object.freeze({ mina: 2, salvaje: 4, desierto: 5, cementerio: 6, tundra: 7,
                                      // (2026-10-25) El glaciar, la caverna y la pradera.
                                      glaciar: 8, caverna: 9, pradera: 10 });
function gfNivelMinimoSala(sala) {
  const b = salaBase(String(sala || ''));
  return Object.prototype.hasOwnProperty.call(GF_NIVEL_MAPA, b) ? GF_NIVEL_MAPA[b] : 0;
}
/** El nivel del personaje: la experiencia vive en GamePlayer y en PlayerStats (la mayor manda). */
async function gfNivelDeJugador(gp) {
  if (!gp) return 0;
  let exp = Math.max(0, Number(gp.nivel_exp) || 0);
  try {
    const st = await PlayerStats.findOne({ playerName: gp.playerName }).select('exp').lean();
    if (st) exp = Math.max(exp, Number(st.exp) || 0);
  } catch (_) {}
  return nivelPorExperiencia(exp);
}

const tesoroSchema = new mongoose.Schema({
  _id:       { type: String, default: TESORO_ID },
  saldo:     { type: Number, default: 0 },
  reservado: { type: Number, default: 0 },
  ingresado: { tienda: { type: Number, default: 0 }, p2p: { type: Number, default: 0 }, admin: { type: Number, default: 0 },
               // (2026-10-26) La comisión de los cambios de moneda (solo para este tesoro).
               cambio: { type: Number, default: 0 } },
  ingresos:  { tienda: { type: Number, default: 0 }, p2p: { type: Number, default: 0 }, cambio: { type: Number, default: 0 } },
  pagado:    { free: { type: Number, default: 0 }, vip: { type: Number, default: 0 } },
  pagos:     { free: { type: Number, default: 0 }, vip: { type: Number, default: 0 } },
  retirado:  { type: Number, default: 0 },
  caducados: { type: Number, default: 0 },
  // (2026-10-28) Lo destruido: quemas del panel y monedas de monstruos que nadie recogió.
  quemado:   { type: Number, default: 0 },
  config:    { type: mongoose.Schema.Types.Mixed, default: null }
}, { collection: 'tesoro', timestamps: true, versionKey: false, minimize: false });
const Tesoro = mongoose.models.Tesoro || mongoose.model('Tesoro', tesoroSchema);

const tesoroMovSchema = new mongoose.Schema({
  t:          { type: Date, default: Date.now },
  tipo:       { type: String, enum: ['ingreso', 'pago', 'ajuste'], required: true },
  origen:     { type: String, default: '' },           // tienda | p2p | monstruo | admin | cambio | viajes | vip | revivir | compra_oro
  // (2026-10-26) De qué tesoro es: 'circular' (o nada, los de antes) o 'juego'.
  tesoro:     { type: String, default: 'circular' },
  bronce:     { type: Number, required: true },
  playerName: { type: String, default: null },
  vip:        { type: Boolean, default: null },
  nivel:      { type: Number, default: null },
  detalle:    { type: String, default: '' },
  ref:        { type: String }                         // solo la tienda: cuenta una vez
}, { collection: 'tesoro_movimientos', versionKey: false });
tesoroMovSchema.index({ t: 1 }, { expireAfterSeconds: 400 * 86400 });
tesoroMovSchema.index({ ref: 1 }, { unique: true, sparse: true });
tesoroMovSchema.index({ tipo: 1, t: -1 });
const TesoroMov = mongoose.models.TesoroMov || mongoose.model('TesoroMov', tesoroMovSchema);

// =============================================================================
// EL TESORO DEL JUEGO                                              (2026-10-26)
// =============================================================================
// "Son dos tesoros: el de la economía circular (la recompensa de los jugadores,
// el de arriba) y el tesoro del JUEGO." Al del juego van: el 3,5 % de cada
// comisión de mercado (tienda y P2P), los viajes del mapa (M), los VIP y el
// elixir de revivir del alquimista. Y el zkLTC de las compras de oro, que se
// apunta aparte (en gwei): es moneda de fuera.
const TESORO_JUEGO_ID = 'juego';
// (2026-10-28) + 'servicios': lo que se cobra por fundir y craftear (ver "LA ECONOMÍA, 2.ª PARTE").
const TESORO_JUEGO_ORIGENES = ['tienda', 'p2p', 'viajes', 'vip', 'revivir', 'admin', 'servicios'];
const _cero = () => ({ type: Number, default: 0 });
const tesoroJuegoSchema = new mongoose.Schema({
  _id:       { type: String, default: TESORO_JUEGO_ID },
  saldo:     _cero(),                                   // bronce
  retirado:  _cero(),
  quemado:   _cero(),                                   // (2026-10-28) lo quemado desde el panel
  ingresado: Object.fromEntries(TESORO_JUEGO_ORIGENES.map((k) => [k, _cero()])),
  ingresos:  Object.fromEntries(TESORO_JUEGO_ORIGENES.map((k) => [k, _cero()])),
  zkltc:     { gwei: _cero(), compras: _cero(), oro: _cero() },
  config:    { type: mongoose.Schema.Types.Mixed, default: null }   // el precio del oro (economiaConfig)
}, { collection: 'tesoro_juego', timestamps: true, versionKey: false, minimize: false });
const TesoroJuego = mongoose.models.TesoroJuego || mongoose.model('TesoroJuego', tesoroJuegoSchema);
TesoroJuego.init().catch((e) => console.warn('⚠️  tesoro del juego: índices:', e.message));

/** De una comisión de mercado (el 5 %), la parte de la economía circular (el 1,5 %). */
function tesoroParteCircular(bronce) {
  return Math.floor(Math.max(0, Number(bronce) || 0) * TESORO_CIRCULAR_BPS / TESORO_COMISION_BPS);
}
/** Al tesoro del juego (bronce; en negativo, una devolución). Nunca rompe a quien llama. */
async function tesoroJuegoIngresar(origen, bronce, playerName, detalle) {
  const n = Math.round(Number(bronce) || 0);
  if (!n || !TESORO_JUEGO_ORIGENES.includes(origen)) return;
  try {
    await TesoroJuego.updateOne({ _id: TESORO_JUEGO_ID },
      { $inc: { saldo: n, ['ingresado.' + origen]: n, ['ingresos.' + origen]: n > 0 ? 1 : 0 } }, { upsert: true });
    await TesoroMov.create({ tesoro: 'juego', tipo: n > 0 ? 'ingreso' : 'ajuste', origen, bronce: n,
                             playerName: playerName || null, detalle: String(detalle || '').slice(0, 200) });
  } catch (e) { console.warn('⚠️  tesoro del juego (' + origen + '):', e.message); }
}
/** Al tesoro de la economía circular, fuera de la tienda (los cambios de moneda). */
async function tesoroCircularIngresar(origen, bronce, playerName, detalle) {
  const n = Math.max(0, Math.floor(Number(bronce) || 0));
  if (!n) return;
  try {
    await Tesoro.updateOne({ _id: TESORO_ID }, { $inc: { saldo: n, ['ingresado.' + origen]: n, ['ingresos.' + origen]: 1 } }, { upsert: true });
    await TesoroMov.create({ tipo: 'ingreso', origen, bronce: n, playerName: playerName || null, detalle: String(detalle || '').slice(0, 200) });
  } catch (e) { console.warn('⚠️  tesoro circular (' + origen + '):', e.message); }
}

/* LA COMISIÓN DE LOS CAMBIOS (2026-10-26): "solo para la economía circular (los
   drops), de menor a mayor porque empezamos de oro a plata y de plata a bronce:
   el oro menor, la plata media y el bronce algo más". Se mira la moneda que se
   ENTREGA y se cobra en la PEQUEÑA del par, sobre el valor del cambio:
     oro → plata   1 %   (100 de oro dan 99.000 de plata)
     plata → oro   2 %   (1 de oro cuesta 1.020 de plata)
     plata → bronce 2 %  (1 de plata da 980 de bronce)
     bronce → plata 3 %  (1 de plata cuesta 1.030 de bronce)
   `qty` en la unidad GRANDE del par, como la ruta del cambio. */
const CAMBIO_COMISION_BPS = Object.freeze({ oro: 100, plata: 200, bronce: 300 });
function gfComisionCambio(direction, qty) {
  const q = Math.max(0, Math.floor(Number(qty) || 0));
  const entrega = { goldToSilver: 'oro', silverToGold: 'plata', silverToBronze: 'plata', bronzeToSilver: 'bronce' }[direction];
  const pequena = { goldToSilver: 'plata', silverToGold: 'plata', silverToBronze: 'bronce', bronzeToSilver: 'bronce' }[direction];
  if (!entrega || !q) return { moneda: pequena || null, cantidad: 0, bronce: 0, bps: 0 };
  const bps = CAMBIO_COMISION_BPS[entrega];
  const cantidad = Math.max(1, Math.ceil(q * 1000 * bps / 10000));
  return { moneda: pequena, cantidad, bronce: cantidad * TESORO_BRONCE_POR[pequena], bps };
}
// Las colecciones existen antes de la primera venta P2P: crear una colección
// DENTRO de una transacción falla en los Mongo antiguos.
Promise.all([Tesoro.init(), TesoroMov.init()]).catch((e) => console.warn('⚠️  tesoro: índices:', e.message));

function _diaUTC() { return new Date().toISOString().slice(0, 10); }
const _tesoroRacha = new Map();        // playerName -> monstruos seguidos sin premio (la "suerte")
const _tesoroDia = new Map();          // playerName -> { dia, n }  premios de hoy
const _tesoroTiendaDia = new Map();    // playerName -> { dia, bronce }  comisión de tienda contada hoy
setInterval(() => {
  const hoy = _diaUTC();
  for (const [k, v] of _tesoroDia) if (v.dia !== hoy) _tesoroDia.delete(k);
  for (const [k, v] of _tesoroTiendaDia) if (v.dia !== hoy) _tesoroTiendaDia.delete(k);
  if (_tesoroRacha.size > 50000) _tesoroRacha.clear();
}, 60 * 60 * 1000).unref();

/** Cualquier configuración que llegue, acotada a lo que tiene sentido. */
function tesoroNormalizarConfig(c) {
  const B = TESORO_CONFIG_BASE, src = (c && typeof c === 'object') ? c : {};
  const num = (v, def, min, max) => { const n = Number(v); return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : def; };
  const m = src.manual && typeof src.manual === 'object' ? src.manual : {};
  const a = src.auto && typeof src.auto === 'object' ? src.auto : {};
  const out = {
    activo: typeof src.activo === 'boolean' ? src.activo : B.activo,
    modo: src.modo === 'manual' ? 'manual' : 'auto',
    manual: { free: num(m.free, B.manual.free, 0, 75), vip: num(m.vip, B.manual.vip, 0, 75),
              conBonos: typeof m.conBonos === 'boolean' ? m.conBonos : B.manual.conBonos },
    auto: { baseFree: num(a.baseFree, B.auto.baseFree, 0, 50), baseVip: num(a.baseVip, B.auto.baseVip, 0, 50),
            porNivel: num(a.porNivel, B.auto.porNivel, 0, 2), nivelTope: Math.round(num(a.nivelTope, B.auto.nivelTope, 1, 150)),
            rachaPaso: num(a.rachaPaso, B.auto.rachaPaso, 0, 5), rachaTope: num(a.rachaTope, B.auto.rachaTope, 0, 30) },
    parteDelTesoro: num(src.parteDelTesoro, B.parteDelTesoro, 0.01, 5),
    pagoMin: Math.round(num(src.pagoMin, B.pagoMin, 1, 1000000)),
    pagoMax: Math.round(num(src.pagoMax, B.pagoMax, 1, 1e12)),
    vipExtraPago: num(src.vipExtraPago, B.vipExtraPago, 1, 5),
    topeDiario: Math.round(num(src.topeDiario, B.topeDiario, 1, 500))
  };
  if (out.pagoMax < out.pagoMin) out.pagoMax = out.pagoMin;
  return out;
}
let _tesoroCfg = null, _tesoroCfgEn = 0;
async function tesoroConfig() {
  if (_tesoroCfg && Date.now() - _tesoroCfgEn < 10000) return _tesoroCfg;
  let guardada = null;
  try { const t = await Tesoro.findById(TESORO_ID).select('config').lean(); guardada = t && t.config; }
  catch (e) { if (_tesoroCfg) return _tesoroCfg; }
  _tesoroCfg = tesoroNormalizarConfig(guardada);
  _tesoroCfgEn = Date.now();
  return _tesoroCfg;
}

/** Probabilidad (0..TESORO_PROB_MAX) de que un monstruo suelte monedas del tesoro. */
function tesoroProbabilidad(cfg, o) {
  const a = cfg.auto, nivel = Math.max(0, Number(o.nivel) || 0), racha = Math.max(0, Number(o.racha) || 0);
  const bonos = Math.min(nivel, a.nivelTope) * a.porNivel + Math.min(racha * a.rachaPaso, a.rachaTope);
  let pct;
  if (cfg.modo === 'manual') pct = (o.vip ? cfg.manual.vip : cfg.manual.free) + (cfg.manual.conBonos ? bonos : 0);
  else pct = (o.vip ? a.baseVip : a.baseFree) + bonos;
  if (o.jefe) pct *= 2;
  return Math.max(0, Math.min(TESORO_PROB_MAX, pct / 100));
}
/** Cuánto (bronce entero). `azar` en 0..1 (por defecto, Math.random). */
function tesoroCantidad(cfg, saldo, o, azar) {
  const r = Number.isFinite(azar) ? azar : Math.random();
  const dureza = Math.min(4, Math.max(0.6, (Number(o.exp) || 100) / 150));
  const nivel = Math.max(0, Math.min(40, Number(o.nivel) || 0));
  let c = Math.max(0, Number(saldo) || 0) * (cfg.parteDelTesoro / 100) * dureza *
          (o.vip ? cfg.vipExtraPago : 1) * (1 + nivel * 0.02) * (o.jefe ? 2.5 : 1) * (0.7 + 0.6 * r);
  c = Math.min(c, cfg.pagoMax, Math.max(0, Number(saldo) || 0));
  return Math.floor(c);
}

/* Las reservas que quedaron colgadas (el proceso anterior se cayó con montones
   sin recoger) vuelven al saldo UNA vez, antes de la primera reserva nueva. */
let _tesoroListo = null;
function tesoroListo() {
  if (!_tesoroListo) {
    _tesoroListo = Tesoro.updateOne({ _id: TESORO_ID, reservado: { $gt: 0 } },
      [{ $set: { saldo: { $add: ['$saldo', '$reservado'] }, reservado: 0 } }])
      .then((r) => { if (r && r.modifiedCount) console.log('🏦 tesoro: las reservas del arranque anterior vuelven al saldo'); return true; })
      .catch((e) => { _tesoroListo = null; console.warn('⚠️  tesoro: reservas del arranque:', e.message); return false; });
  }
  return _tesoroListo;
}

/** ¿Suelta monedas este monstruo? null, o { cantidad, vip, nivel, prob } YA reservado. */
async function tesoroIncentivo(gp, def, tipo, nivel) {
  if (!gp || !gfNombreValido(gp.Username)) return null;
  const cfg = await tesoroConfig();
  if (!cfg.activo) return null;
  if (!(await tesoroListo())) return null;
  const quien = gp.playerName, hoy = _diaUTC();
  const dia = _tesoroDia.get(quien);
  const deHoy = dia && dia.dia === hoy ? dia.n : 0;
  if (deHoy >= cfg.topeDiario) return null;
  const vip = await gfTieneVipPorDireccion(gp.address);
  const racha = _tesoroRacha.get(quien) || 0;
  const jefe = /^jefe_/.test(String(tipo || ''));
  const prob = tesoroProbabilidad(cfg, { vip, nivel, racha, jefe });
  if (!(Math.random() < prob)) { _tesoroRacha.set(quien, racha + 1); return null; }
  const t = await Tesoro.findById(TESORO_ID).select('saldo').lean();
  let cantidad = tesoroCantidad(cfg, t ? t.saldo : 0, { vip, nivel, exp: def && def.exp, jefe });
  /* (2026-10-26) "Los enemigos no sueltan monedas de bronce, solo objetos." El
     pago es una parte del saldo (0,25 % con sus multiplicadores): con menos de
     unos 25 000 de bronce en el tesoro no llegaba nunca al mínimo y el premio
     se descartaba en silencio aunque el tesoro pudiera pagarlo. Si el tesoro
     tiene para el mínimo, se paga el mínimo. Sin saldo para eso, nada (la
     regla de siempre: lo que sale, sale del tesoro). */
  const saldoTesoro = t ? Math.max(0, Math.floor(Number(t.saldo) || 0)) : 0;
  if (cantidad < cfg.pagoMin && saldoTesoro >= cfg.pagoMin) cantidad = cfg.pagoMin;
  if (!(cantidad >= cfg.pagoMin)) return null;                 // el tesoro no da para un pago: la racha sigue
  const r = await Tesoro.findOneAndUpdate({ _id: TESORO_ID, saldo: { $gte: cantidad } },
    { $inc: { saldo: -cantidad, reservado: cantidad } }, { new: true, projection: { saldo: 1 } }).lean();
  if (!r) return null;
  _tesoroRacha.set(quien, 0);
  _tesoroDia.set(quien, { dia: hoy, n: deHoy + 1 });
  return { cantidad, vip, nivel, prob };
}
async function tesoroDevolverReserva(cantidad, motivo) {
  const n = Math.max(0, Math.floor(Number(cantidad) || 0));
  if (!n) return;
  try { await Tesoro.updateOne({ _id: TESORO_ID }, { $inc: { saldo: n, reservado: -n, caducados: motivo === 'caducado' ? 1 : 0 } }); }
  catch (e) { console.warn('⚠️  tesoro: devolver reserva:', e.message); }
}
/** Al pisar el montón: a la moneda de bronce del jugador (no al inventario). */
async function tesoroPagar(gp, b) {
  const doc = await gfDevolverStat(gp.playerName, 'bronce', b.cantidad);
  if (!doc) { await tesoroDevolverReserva(b.cantidad, 'sin_stats'); return null; }
  const grupo = b.incentivo && b.incentivo.vip ? 'vip' : 'free';
  try {
    await Tesoro.updateOne({ _id: TESORO_ID }, { $inc: { reservado: -b.cantidad, ['pagado.' + grupo]: b.cantidad, ['pagos.' + grupo]: 1 } });
  } catch (e) { console.warn('⚠️  tesoro: apuntar el pago:', e.message); }
  TesoroMov.create({ tipo: 'pago', origen: 'monstruo', bronce: b.cantidad, playerName: gp.playerName, vip: grupo === 'vip',
                     nivel: b.incentivo ? b.incentivo.nivel : null, detalle: b.incentivo ? String(b.incentivo.monstruo || '') : '' })
    .catch((e) => console.warn('⚠️  tesoro: movimiento de pago:', e.message));
  console.log(`🏦 ${gp.playerName} recogió ${b.cantidad} de bronce del tesoro (${grupo})`);
  return doc;
}

/** La comisión de la tienda del juego (bronce). La MISMA cuenta que tienda_sistema.js (_comisionBronce). */
function tesoroComisionTienda(itemId, operacion, cantidad) {
  // (2026-10-28) Con el precio de HOY (el índice de precios y lo que cambie el panel: "LA ECONOMÍA, 2.ª PARTE").
  const p = typeof eco2PrecioTienda === 'function' ? eco2PrecioTienda(itemId)
    : (Object.prototype.hasOwnProperty.call(TIENDA_PRECIOS, itemId) ? TIENDA_PRECIOS[itemId] : null);
  if (!p) return 0;
  const unidad = Number(operacion === 'compra' ? p[0] : p[1]) || 0;
  const bruto = unidad * (p[2] === 'p' ? TESORO_BRONCE_POR.plata : p[2] === 'b' ? TESORO_BRONCE_POR.bronce : TESORO_BRONCE_POR.oro) *
    (Math.floor(Number(cantidad)) || 0);
  return bruto > 0 ? Math.max(1, Math.round(bruto * TESORO_COMISION_BPS / 10000)) : 0;
}

app.post('/api/tesoro/comision', apiLimiter, authMiddleware, csrfProtection, async (req, res) => {
  try {
    const gp = await jugadorDeLaSesion(req);
    if (!gp) return res.status(403).json({ error: 'no_autorizado' });
    const b = req.body || {};
    const operacion = String(b.operacion || ''), itemId = String(b.itemId || '').slice(0, 60);
    const cantidad = Math.floor(Number(b.cantidad) || 0), ref = String(b.ref || '');
    if (operacion !== 'compra' && operacion !== 'venta') return res.status(400).json({ error: 'operacion_invalida' });
    if (!(cantidad >= 1 && cantidad <= 999)) return res.status(400).json({ error: 'cantidad_invalida' });
    if (!/^[A-Za-z0-9_-]{8,64}$/.test(ref)) return res.status(400).json({ error: 'ref_invalida' });
    const total = tesoroComisionTienda(itemId, operacion, cantidad);
    if (!total) return res.status(400).json({ error: 'objeto_sin_precio' });
    const hoy = _diaUTC(), d = _tesoroTiendaDia.get(gp.playerName);
    const llevado = d && d.dia === hoy ? d.bronce : 0;
    const bronce = Math.max(0, Math.min(total, TESORO_TOPE_TIENDA_DIA - llevado));
    if (!bronce) return res.json({ ok: true, bronce: 0, tope: true });
    // (2026-10-26) El 5 % se reparte: el 1,5 % a la economía circular y el 3,5 % al tesoro del juego.
    const circular = tesoroParteCircular(bronce), juego = bronce - circular;
    try {
      await TesoroMov.create({ tipo: 'ingreso', origen: 'tienda', bronce: circular, playerName: gp.playerName,
                               detalle: operacion + ' ' + itemId + ' x' + cantidad, ref: 'tienda:' + gp.playerName + ':' + ref });
    } catch (e) {
      if (e && e.code === 11000) return res.json({ ok: true, bronce: 0, repetido: true });
      throw e;
    }
    _tesoroTiendaDia.set(gp.playerName, { dia: hoy, bronce: llevado + bronce });
    await Tesoro.updateOne({ _id: TESORO_ID }, { $inc: { saldo: circular, 'ingresado.tienda': circular, 'ingresos.tienda': 1 } }, { upsert: true });
    await tesoroJuegoIngresar('tienda', juego, gp.playerName, operacion + ' ' + itemId + ' x' + cantidad);
    return res.json({ ok: true, bronce, circular, juego });
  } catch (e) {
    console.error('POST /api/tesoro/comision:', e);
    return res.status(500).json({ error: 'internal_error' });
  }
});

/* ── EL PANEL ──────────────────────────────────────────────────────────── */
function tesoroPublico(t) {
  const x = t || {};
  const sub = (o, k) => Math.max(0, Number(o && o[k]) || 0);
  return {
    saldo: Math.max(0, Number(x.saldo) || 0), reservado: Math.max(0, Number(x.reservado) || 0),
    ingresado: { tienda: sub(x.ingresado, 'tienda'), p2p: sub(x.ingresado, 'p2p'), admin: sub(x.ingresado, 'admin'), cambio: sub(x.ingresado, 'cambio') },
    ingresos: { tienda: sub(x.ingresos, 'tienda'), p2p: sub(x.ingresos, 'p2p'), cambio: sub(x.ingresos, 'cambio') },
    pagado: { free: sub(x.pagado, 'free'), vip: sub(x.pagado, 'vip') },
    pagos: { free: sub(x.pagos, 'free'), vip: sub(x.pagos, 'vip') },
    retirado: Math.max(0, Number(x.retirado) || 0), caducados: Math.max(0, Number(x.caducados) || 0),
    quemado: Math.max(0, Number(x.quemado) || 0),
    actualizado: x.updatedAt || null
  };
}

app.get('/api/admin/tesoro', adminAuth, apiLimiter, async (req, res) => {
  try {
    const ahora = Date.now(), hace30 = new Date(ahora - 30 * 86400000), hace24h = new Date(ahora - 86400000);
    const limites = [0, expTotalParaNivel(2), expTotalParaNivel(4), expTotalParaNivel(5), expTotalParaNivel(6), expTotalParaNivel(7), Number.MAX_SAFE_INTEGER];
    const [t, cfg, cuentas, vipLista, conNombre, activos24h, grupos, ultimos, top, buckets] = await Promise.all([
      Tesoro.findById(TESORO_ID).lean(),
      tesoroConfig(),
      GamePlayer.countDocuments({}),
      VipEstado.find({ fin: { $gt: new Date() } }).select('playerName').lean(),
      GamePlayer.countDocuments({ Username: { $exists: true, $nin: [null, '', '---'] } }),
      PlayerPlaytime.countDocuments({ ultimaVez: { $gte: hace24h } }),
      TesoroMov.aggregate([
        { $match: { t: { $gte: hace30 }, tesoro: { $nin: ['juego', 'reserva'] } } },
        { $group: { _id: { dia: { $dateToString: { format: '%Y-%m-%d', date: '$t', timezone: 'UTC' } }, tipo: '$tipo', origen: '$origen', vip: '$vip' },
                    bronce: { $sum: '$bronce' }, n: { $sum: 1 } } }
      ]),
      TesoroMov.find({ tesoro: { $nin: ['juego', 'reserva'] } }).sort({ t: -1 }).limit(30).lean(),
      TesoroMov.aggregate([
        { $match: { tipo: 'pago', t: { $gte: hace30 } } },
        { $group: { _id: '$playerName', bronce: { $sum: '$bronce' }, n: { $sum: 1 }, vip: { $last: '$vip' } } },
        { $sort: { bronce: -1 } }, { $limit: 10 }
      ]),
      GamePlayer.aggregate([
        { $project: { e: { $convert: { input: '$nivel_exp', to: 'double', onError: 0, onNull: 0 } } } },
        { $bucket: { groupBy: '$e', boundaries: limites, default: 'otros', output: { n: { $sum: 1 } } } }
      ])
    ]);
    const nombresVip = vipLista.map(v => v.playerName).filter(Boolean);
    const vipActivos24h = nombresVip.length
      ? await PlayerPlaytime.countDocuments({ ultimaVez: { $gte: hace24h }, playerName: { $in: nombresVip } }) : 0;

    // La serie de los últimos 30 días (UTC), un punto por día aunque esté vacío.
    const dias = [];
    for (let i = 29; i >= 0; i--) dias.push(new Date(ahora - i * 86400000).toISOString().slice(0, 10));
    const porDia = new Map(dias.map(d => [d, { dia: d, tienda: 0, p2p: 0, cambio: 0, admin: 0, pagoFree: 0, pagoVip: 0, premios: 0 }]));
    for (const g of grupos) {
      const fila = porDia.get(g._id.dia);
      if (!fila) continue;
      if (g._id.tipo === 'ingreso' && (g._id.origen === 'tienda' || g._id.origen === 'p2p' || g._id.origen === 'cambio')) fila[g._id.origen] += g.bronce;
      else if (g._id.tipo === 'ajuste' && g.bronce > 0) fila.admin += g.bronce;
      else if (g._id.tipo === 'pago') { fila[g._id.vip ? 'pagoVip' : 'pagoFree'] += g.bronce; fila.premios += g.n; }
    }

    // Cuántos llegan a cada mapa (el nivel sale de la experiencia de GamePlayer).
    const tramos = { 'otros': 0 };
    for (const b of buckets) tramos[String(b._id)] = b.n;
    const enTramo = (desde) => limites.filter(l => l >= desde && l < Number.MAX_SAFE_INTEGER).reduce((s, l) => s + (tramos[String(l)] || 0), 0);
    const mapas = Object.keys(GF_NIVEL_MAPA).map(sala => ({ sala, nivel: GF_NIVEL_MAPA[sala], jugadores: enTramo(expTotalParaNivel(GF_NIVEL_MAPA[sala])) }));
    const niveles = [
      { tramo: '1', jugadores: tramos['0'] || 0 }, { tramo: '2-3', jugadores: tramos[String(limites[1])] || 0 },
      { tramo: '4', jugadores: tramos[String(limites[2])] || 0 }, { tramo: '5', jugadores: tramos[String(limites[3])] || 0 },
      { tramo: '6', jugadores: tramos[String(limites[4])] || 0 }, { tramo: '7+', jugadores: tramos[String(limites[5])] || 0 }
    ];

    // Lo que daría ahora, con la configuración de ahora (para el panel).
    const saldo = t ? Math.max(0, Number(t.saldo) || 0) : 0;
    const ejemplos = [1, 4, 7, 10, 20, 40].map(nivel => ({
      nivel,
      free: tesoroProbabilidad(cfg, { vip: false, nivel, racha: 0 }), vip: tesoroProbabilidad(cfg, { vip: true, nivel, racha: 0 }),
      freeRacha: tesoroProbabilidad(cfg, { vip: false, nivel, racha: 1000 }), vipRacha: tesoroProbabilidad(cfg, { vip: true, nivel, racha: 1000 }),
      pagoFree: tesoroCantidad(cfg, saldo, { vip: false, nivel, exp: 130 }, 0.5), pagoVip: tesoroCantidad(cfg, saldo, { vip: true, nivel, exp: 130 }, 0.5)
    }));

    return res.json({
      ok: true, tesoro: tesoroPublico(t), config: cfg, base: TESORO_CONFIG_BASE, comisionBps: TESORO_CIRCULAR_BPS,
      comisionTotalBps: TESORO_COMISION_BPS, cambioBps: CAMBIO_COMISION_BPS,
      bronce: TESORO_BRONCE_POR, probMax: TESORO_PROB_MAX, ejemplos,
      jugadores: { cuentas, vip: nombresVip.length, free: Math.max(0, cuentas - nombresVip.length), conNombre,
                   sinNombre: Math.max(0, cuentas - conNombre), activos24h, vipActivos24h },
      niveles, mapas, serie: dias.map(d => porDia.get(d)),
      top: top.map(r => ({ playerName: r._id, bronce: r.bronce, premios: r.n, vip: !!r.vip })),
      ultimos: ultimos.map(m => ({ t: m.t, tipo: m.tipo, origen: m.origen, bronce: m.bronce, playerName: m.playerName,
                                   vip: m.vip, nivel: m.nivel, detalle: m.detalle }))
    });
  } catch (e) {
    console.error('GET /api/admin/tesoro:', e);
    return res.status(500).json({ error: 'internal_error' });
  }
});

