    coral:     { vel: 1.02, vida: 0.94, arma: 'escupitajo', super: 'bandada',   etiqueta: 'Coral' },
    topo:      { vel: 0.96, vida: 1.05, arma: 'mordisco',   super: 'embestida', etiqueta: 'Mole' },
